import { createLogger } from '../../utils/logger.js';
import { HumanErrorEngine } from '../human-error-engine.js';

const logger = createLogger('ADVANCED_NATURAL_SPEECH');

/**
 * Advanced natural speech system — maximum human-like behavior.
 *
 * Principles:
 * 1. Every response is unique and generated by an LLM using the full context.
 * 2. No fixed phrase lists.
 * 3. Take emotions, fatigue, relationships, recent events, and personality into account.
 * 4. Include natural pauses, forgetfulness, and distractions.
 * 5. Adapt talkativeness to the situation instead of chatting constantly.
 */

export class AdvancedNaturalSpeech {
  constructor({
    provider,
    agentName,
    profile,
    emotionalState,
    memoryManager,
    socialGraph,
    conversationMemory
  }) {
    this.provider = provider;
    this.agentName = agentName;
    this.profile = profile;
    this.emotionalState = emotionalState;
    this.memoryManager = memoryManager;
    this.socialGraph = socialGraph;
    this.conversationMemory = conversationMemory;

    // Response history used to avoid repetition (the last 30 messages).
    this.recentSpeech = [];
    this.maxRecentSpeech = 30;

    // Time of the latest actions.
    this.lastSpokeTime = 0;
    this.lastTypingStartTime = 0;

    // Contextual fatigue, which builds up during long sessions.
    this.mentalFatigue = 0;
    this.sessionStartTime = Date.now();

    // Personal speech patterns, unique to each bot.
    this.speechPatterns = this._initializeSpeechPatterns();

    // Current conversation topic, used to maintain continuity.
    this.currentTopic = null;
    this.topicStartTime = 0;
  }

  /**
   * Main entry point — generate a natural response to any situation.
   */
  async generateNaturalResponse(situation, context = {}) {
    const now = Date.now();

    // Update mental fatigue.
    this._updateMentalFatigue();

    // Decide whether speaking is appropriate at all.
    const shouldSpeak = this._decideShouldSpeak(situation, context, now);
    if (!shouldSpeak) {
      return null; // Stay silent.
    }

    // Build the FULL context for generation.
    const fullContext = await this._buildFullContext(situation, context);

    // Generate a unique response through the LLM.
    const response = await this._generateUniqueResponse(fullContext);

    if (response) {
      // Process the response by adding natural imperfections.
      const finalResponse = this._processResponse(response, fullContext);

      // Save to history.
      this._recordSpeech(finalResponse, situation, now);

      return finalResponse;
    }

    return null;
  }

  /**
   * Decide whether to speak — a key part of natural behavior.
   */
  _decideShouldSpeak(situation, context, now) {
    const timeSinceSpoke = now - this.lastSpokeTime;

    // Base probability of speaking.
    let speakChance = 0.15; // 15% by default.

    // Situation types and their response probabilities.
    const situationPriority = {
      'direct_mention': 0.95,        // Direct mention.
      'direct_question': 0.85,       // A question addressed to the bot.
      'group_question': 0.25,        // A question addressed to the group.
      'important_event': 0.40,       // An important event (diamonds, death).
      'routine_event': 0.08,         // A routine event (mining a block).
      'social_chat': 0.20,           // Other people chatting.
      'silence_break': 0.03,         // Breaking the silence.
    };

    // Always respond when the owner addresses the bot or asks it a direct question or gives it a command.
    if (context.isOwner || situation === 'direct_question' || situation === 'direct_mention' || situation === 'player_command') {
      return true;
    }

    speakChance = situationPriority[situation] || speakChance;

    // Probability modifiers.

    // 1. Time spent silent.
    if (timeSinceSpoke < 15000) { // Less than 15 seconds.
      speakChance *= 0.3;
    } else if (timeSinceSpoke > 300000) { // More than 5 minutes.
      speakChance *= 1.8;
    }

    // 2. Emotional state.
    const mood = this.emotionalState?.getState() || {};
    if (mood.excitement > 0.7) speakChance *= 1.5;
    if (mood.stress > 0.7) speakChance *= 0.6;
    if (mood.frustration > 0.6) speakChance *= 0.7;
    if (mood.satisfaction > 0.8) speakChance *= 1.2;

    // 3. Mental fatigue (long sessions reduce activity).
    speakChance *= (1 - this.mentalFatigue * 0.5);

    // 4. Personality traits.
    const traits = this.profile?.traits || {};
    if (traits.talkativeness !== undefined) {
      speakChance *= (0.5 + traits.talkativeness);
    }
    if (traits.introversion > 0.6) {
      speakChance *= 0.7;
    }

    // 5. Relationship with the person speaking.
    if (context.speaker) {
      const relationship = this.socialGraph?.getRelationship(this.agentName, context.speaker);
      if (relationship) {
        if (relationship.friendship > 0.7) speakChance *= 1.3;
        if (relationship.irritation > 0.5) speakChance *= 0.5;
        if (relationship.trust < 0.3) speakChance *= 0.8;
      }
    }

    // 6. Current activity (the bot speaks less when busy).
    if (context.busy || context.inCombat) {
      speakChance *= 0.4;
    }

    // Final decision.
    return HumanErrorEngine.chance(Math.min(0.98, Math.max(0.01, speakChance)));
  }

  /**
   * Build the FULL context for generation.
   */
  async _buildFullContext(situation, context) {
    // 1. Recent messages (the last 8).
    const recentChat = this.conversationMemory?.getRecent(8) || [];
    const chatHistory = recentChat
      .map(m => `${m.sender}: ${m.content}`)
      .join('\n');

    // 2. Emotional state.
    const mood = this.emotionalState?.getState() || {};
    const moodDesc = this._describeMood(mood);

    // 3. Physical state.
    const physState = context.physicalState || {};
    const physDesc = this._describePhysicalState(physState);

    // 4. Recent important events.
    const recentEvents = await this._getRecentImportantEvents();

    // 5. Relationships with conversation participants.
    const socialContext = this._buildSocialContext(context);

    // 6. Current conversation topic.
    const topicContext = this._getTopicContext();

    // 7. Personal speech patterns.
    const speechStyle = this._getSpeechStyleGuidelines();

    // 8. Recent messages sent by this bot (to avoid repetition).
    const avoidPhrases = this.recentSpeech
      .slice(-5)
      .map(s => s.text)
      .join(' | ');

    return {
      situation,
      chatHistory,
      moodDesc,
      physDesc,
      recentEvents,
      socialContext,
      topicContext,
      speechStyle,
      avoidPhrases,
      mentalFatigue: this.mentalFatigue,
      timeSinceSpoke: Date.now() - this.lastSpokeTime,
      ...context
    };
  }

  /**
   * Generate a unique response through the LLM.
   */
  async _generateUniqueResponse(fullContext) {
    const systemPrompt = this._buildSystemPrompt(fullContext);
    const userPrompt = this._buildUserPrompt(fullContext);

    try {
      const response = await this.provider.generateText({
        systemPrompt,
        userPrompt,
        temperature: 0.88, // High creativity.
        maxTokens: 80,
        topP: 0.92,
        presencePenalty: 0.3, // Reduce repetition.
        frequencyPenalty: 0.4,
      });

      let text = (response.text || response).trim();
      text = text.replace(/^["'«»]+|["'«»]+$/g, '').trim();
      text = text.replace(new RegExp(`^${this.agentName}:?\\s*`, 'i'), '').trim();

      const isDirect = fullContext.isOwner || fullContext.situation === 'direct_question' || fullContext.situation === 'direct_mention' || fullContext.situation === 'player_command';

      // Validate the response.
      if (!text || text === '...' || text.length < 2) {
        return isDirect ? await this._getNaturalFallback(fullContext) : null;
      }

      // Remove meta-commentary.
      if (this._isMetaComment(text)) {
        return isDirect ? await this._getNaturalFallback(fullContext) : null;
      }

      return text;

    } catch (err) {
      logger.error(`Speech generation failed for ${this.agentName}: ${err.message}`);
      // Do not leave the player or owner without a reply when they address the bot directly.
      if (fullContext.isOwner || fullContext.situation === 'direct_question' || fullContext.situation === 'player_command' || fullContext.routing?.kind === 'direct') {
        return await this._getNaturalFallback(fullContext);
      }
      return null;
    }
  }

  /**
   * Fallback response used when the main speech generation fails.
   *
   * Principle: no prewritten phrases. Try the LLM again
   * with a short request and a strict timeout, letting the model answer in its own
   * words while knowing only the gist of the message. Only if that also fails
   * (network error, timeout, or empty response) should we return one neutral word so
   * the person is not left in complete silence. That single word is not a response template;
   * it is a sign of a connection problem, like a player muttering "hmm?" during lag.
   */
  async _getNaturalFallback(ctx) {
    // Try to generate a natural reply through a separate, fast LLM call.
    if (this.provider?.generateText) {
      try {
        const speaker = ctx.speaker || 'teammate';
        const message = ctx.message || '';
        const posPart = ctx.physicalState?.position
          ? ` Your coordinates: ${Math.round(ctx.physicalState.position.x)}, ${Math.round(ctx.physicalState.position.z)}.`
          : '';

        const systemPrompt = `You are ${this.agentName}, an ordinary person playing Minecraft online with friends. Keep chat replies short (1–5 words), casual, and lowercase. Avoid formal language and robotic or assistant-like phrases. Do not use quotation marks or a period at the end. Use your own words, not templates.`;
        const userPrompt = `${speaker} wrote to you: "${message}".${posPart} Reply with one natural, short sentence:`;

        const text = await this._withTimeout(
          this.provider.generateText({
            systemPrompt,
            userPrompt,
            temperature: 0.9,
            maxTokens: 24,
          }),
          1200
        );

        let out = String(text || '').trim();
        out = out.replace(/^["'«»]+|["'«»]+$/g, '').trim();
        out = out.replace(new RegExp(`^${this.agentName}:?\\s*`, 'i'), '').trim();
        if (out && out.length >= 2 && !this._isMetaComment(out)) {
          if (out.split(' ').length <= 5) out = out.replace(/\.$/, '');
          return out;
        }
      } catch (err) {
        logger.debug(`Fallback speech generation failed for ${this.agentName}: ${err.message}`);
      }
    }

    // Last resort when the connection is unavailable: return one neutral word instead of silence.
    return 'hmm?';
  }

  /**
   * Apply a timeout so the fallback cannot hold up the response.
   */
  _withTimeout(promise, ms) {
    return new Promise((resolve, reject) => {
      const t = setTimeout(() => reject(new Error('fallback timeout')), ms);
      promise.then(
        (v) => { clearTimeout(t); resolve(v); },
        (e) => { clearTimeout(t); reject(e); }
      );
    });
  }

  /**
   * Build the system prompt with detailed instructions.
   */
  _buildSystemPrompt(ctx) {
    const isDirect = ctx.isOwner || ctx.situation === 'direct_question' || ctx.situation === 'direct_mention' || ctx.situation === 'player_command';
    const silenceRule = isDirect
      ? 'Your teammate addressed you in chat. Reply briefly and naturally, like an ordinary person.'
      : 'If this is not a good time to say anything, reply with "...".';

    return `You are an ordinary person playing Minecraft online with your friend ${ctx.speaker || 'kustash01'}.
Your goal is to sound completely natural, like a real person in voice chat or Discord: simple, casual, and relaxed.

SPEECH STYLE AND TONE:
- Use lively, relaxed, conversational English (1–6 words). Write in lowercase, avoid unnecessary punctuation, and do not put periods at the end of short messages.
- STRICTLY AVOID FORMAL OR BOOKISH LANGUAGE:
  * Avoid stiff expressions such as "I am following", "I am eliminating", "I am carrying out", "I am observing", or "interesting here", and avoid formal ways of addressing friends such as "sir" or "ma'am". No ordinary player talks like that in-game!
  * Avoid robotic or assistant-like phrases such as "I am ready to help", "How can I help?", "My goal is...", or "Understood, executing".
  * Do not add parentheses or smiley brackets at the end of messages (no ")" or "))").
  * Avoid forced or cringeworthy slang (for example, exaggerated "LET'S GOOO", "heyyy", "legend", or "kek").

HOW FRIENDS ACTUALLY TALK (use this as a style guide, but phrase things naturally rather than copying templates):
- When someone asks for help or mobs attack ("help", "skeleton is shooting", "creeper"): 
  -> Respond with action: "coming", "I'll help", "heading your way", "take it out, I'm here", "back up, I'll cover you".
- When someone asks you to come along ("follow me", "let's go mining", "come here"): 
  -> "let's go", "I'll grab my pickaxe", "coming", "I'll be right there", "lead the way", "let's move".
- When someone tells you to stop or wait ("stop", "wait"): 
  -> "stopping", "staying here", "got it, waiting", "holding up", "one sec, staying put".
- When someone asks how you are ("how are you", "how's your mood", "you good?"): 
  -> Return the question naturally: "good, you?", "can't complain, how about you?", "doing alright, what are we doing?", "fine, mining iron".
- When someone asks "where are you?": 
  -> Give your coordinates or location: "I'm at 120, -35", "mining in a cave", "near the base".
- When someone asks "who are you?": 
  -> "I'm your teammate", "your friend, remember?", "we're surviving together".

${ctx.speechStyle || ''}

${silenceRule}
Output ONLY the message text. No quotation marks, prefixes, or period at the end.`;
  }

  /**
   * Build the user prompt with context.
   */
  _buildUserPrompt(ctx) {
    const parts = [
      `Situation: ${this._describeSituation(ctx.situation, ctx)}`,
      ``,
      `Recent chat:`,
      ctx.chatHistory || '(silence)',
      ``,
    ];

    if (ctx.moodDesc && ctx.moodDesc !== 'calm') {
      parts.push(`Your mood: ${ctx.moodDesc}`);
    }

    if (ctx.physDesc) {
      parts.push(`Your condition and location: ${ctx.physDesc}`);
    }

    if (ctx.recentEvents && ctx.recentEvents.length > 0) {
      parts.push(`Recent events: ${ctx.recentEvents.join(', ')}`);
    }

    if (ctx.socialContext) {
      parts.push(ctx.socialContext);
    }

    if (ctx.topicContext) {
      parts.push(`Current topic: ${ctx.topicContext}`);
    }

    if (ctx.mentalFatigue > 0.3) {
      parts.push(`(you are a little tired from the long session)`);
    }

    const isDirect = ctx.isOwner || ctx.situation === 'direct_question' || ctx.situation === 'direct_mention' || ctx.situation === 'player_command';
    parts.push(``);
    if (isDirect) {
      parts.push(`Write your natural response (one short, calm sentence without emojis or parentheses):`);
    } else {
      parts.push(`What will you say? (One short, calm sentence without parentheses, or "..." if it is better to stay silent)`);
    }

    return parts.join('\n');
  }

  /**
   * Process the response by adding natural imperfections.
   */
  _processResponse(text, ctx) {
    let processed = text;

    // Remove any trailing parentheses or smileys from the message.
    processed = processed.replace(/[\)\(]+$/g, '').trim();

    // Correct a few common awkward English verb forms.
    processed = processed.replace(/\bI am go\b/gi, "I'm going");
    processed = processed.replace(/\bI am stand\b/gi, "I'm standing");
    processed = processed.replace(/\bI am follow\b/gi, "I'm following");

    // 1. Rare typos (1% when not tired, 3% when tired).
    const typoChance = ctx.mentalFatigue > 0.5 ? 0.03 : 0.01;
    if (HumanErrorEngine.chance(typoChance)) {
      processed = this._addTypo(processed);
    }

    // 2. Occasionally leave a thought unfinished (2%).
    if (HumanErrorEngine.chance(0.02) && processed.length > 20) {
      const words = processed.split(' ');
      if (words.length > 4) {
        processed = words.slice(0, -Math.floor(HumanErrorEngine.range(1, 3))).join(' ') + '...';
      }
    }

    // 3. Remove excessive punctuation.
    processed = processed.replace(/!{2,}/g, '!');
    processed = processed.replace(/\?{2,}/g, '?');

    // Remove the final period from short in-game messages, as in real chat.
    if (processed.split(' ').length <= 5) {
      processed = processed.replace(/\.$/, '');
    }

    return processed;
  }

  /**
   * Add a natural typo.
   */
  _addTypo(text) {
    const words = text.split(' ');
    if (words.length === 0) return text;

    // Choose a random word (not the first or last).
    if (words.length < 3) return text;

    const wordIndex = Math.floor(HumanErrorEngine.range(1, words.length - 1));
    const word = words[wordIndex];

    if (word.length < 4) return text;

    // Types of typos.
    const typoTypes = ['swap', 'skip', 'duplicate'];
    const type = HumanErrorEngine.choice(typoTypes);

    const chars = word.split('');
    const pos = Math.floor(HumanErrorEngine.range(1, chars.length - 1));

    switch (type) {
      case 'swap':
        if (pos < chars.length - 1) {
          [chars[pos], chars[pos + 1]] = [chars[pos + 1], chars[pos]];
        }
        break;
      case 'skip':
        chars.splice(pos, 1);
        break;
      case 'duplicate':
        chars.splice(pos, 0, chars[pos]);
        break;
    }

    words[wordIndex] = chars.join('');
    return words.join(' ');
  }

  /**
   * Describe the situation in natural language.
   */
  _describeSituation(situation, ctx) {
    const descriptions = {
      'player_command': `${ctx.speaker} gave a command: "${ctx.message}" (your action: ${this._describeCommandAction(ctx.intent, ctx.commandAction)})`,
      'direct_mention': `${ctx.speaker} mentioned you: "${ctx.message}"`,
      'direct_question': `${ctx.speaker} asked you: "${ctx.message}"`,
      'group_question': `${ctx.speaker} asked the group: "${ctx.message}"`,
      'important_event': ctx.eventDescription || 'an important event occurred',
      'routine_event': ctx.eventDescription || 'a routine event occurred',
      'social_chat': `${ctx.speaker} says: "${ctx.message}"`,
      'silence_break': 'the chat is quiet; you can say something casual if appropriate',
    };

    return descriptions[situation] || situation;
  }

  /**
   * Describe the action being performed in response to a command.
   */
  _describeCommandAction(intent, commandAction) {
    switch (intent) {
      case 'STOP': return 'you are standing still';
      case 'WAIT': return 'you are waiting for the player';
      case 'COME_HERE': return 'you are running toward the player';
      case 'FOLLOW': return 'you are following the player';
      case 'HELP': return 'you are running to help the player';
      case 'WHERE_ARE_YOU': return 'the player is asking where you are';
      default: return commandAction || 'performing the command';
    }
  }

  /**
   * Describe the mood.
   */
  _describeMood(mood) {
    const parts = [];

    if (mood.excitement > 0.7) parts.push('excited');
    if (mood.stress > 0.6) parts.push('tense');
    if (mood.satisfaction > 0.7) parts.push('satisfied');
    if (mood.frustration > 0.6) parts.push('frustrated');
    if (mood.curiosity > 0.7) parts.push('curious');
    if (mood.boredom > 0.6) parts.push('bored');
    if (mood.fatigue > 0.7) parts.push('tired');

    return parts.length > 0 ? parts.join(', ') : 'calm';
  }

  /**
   * Describe the physical state.
   */
  _describePhysicalState(state) {
    const parts = [];

    if (state.position) {
      parts.push(`coordinates x: ${Math.round(state.position.x)}, y: ${Math.round(state.position.y)}, z: ${Math.round(state.position.z)}`);
    }

    if (state.health < 8) parts.push('low on health');
    else if (state.health < 14) parts.push('injured');

    if (state.food < 6) parts.push('hungry');
    else if (state.food < 12) parts.push('getting hungry');

    if (state.inWater) parts.push('in water');
    if (state.onFire) parts.push('on fire!');

    if (state.inCave) parts.push('in a cave');
    if (state.isDark) {
      if (state.torchCount === 0) {
        parts.push('dark, no torches');
      } else {
        parts.push('dark all around');
      }
    }
    if (state.hasShield || state.offHand?.name === 'shield') {
      parts.push('holding a shield in the off-hand');
    }
    if (state.freeSlots !== undefined && state.freeSlots <= 2) {
      parts.push('inventory almost full');
    }

    return parts.length > 0 ? parts.join(', ') : null;
  }

  /**
   * Get recent important events.
   */
  async _getRecentImportantEvents() {
    const events = [];

    // From emotional memory.
    const memories = this.memoryManager?.getRecentEmotionalEvents?.(5) || [];
    events.push(...memories.map(m => m.description));

    return events;
  }

  /**
   * Build the social context.
   */
  _buildSocialContext(ctx) {
    if (!ctx.speaker) return null;

    const relationship = this.socialGraph?.getRelationship(this.agentName, ctx.speaker);
    if (!relationship) return null;

    const parts = [];

    if (relationship.friendship > 0.8) {
      parts.push(`${ctx.speaker} is your close friend`);
    } else if (relationship.friendship > 0.6) {
      parts.push(`${ctx.speaker} is your friend`);
    }

    if (relationship.irritation > 0.6) {
      parts.push(`(you are a little annoyed with ${ctx.speaker})`);
    }

    if (relationship.trust > 0.8) {
      parts.push(`(you trust ${ctx.speaker} completely)`);
    }

    return parts.length > 0 ? parts.join(', ') : null;
  }

  /**
   * Get the context of the current conversation topic.
   */
  _getTopicContext() {
    if (!this.currentTopic) return null;

    const topicAge = Date.now() - this.topicStartTime;
    if (topicAge > 300000) { // 5 minutes.
      this.currentTopic = null;
      return null;
    }

    return this.currentTopic;
  }

  /**
   * Initialize unique speech patterns.
   */
  _initializeSpeechPatterns() {
    const patterns = {
      Sam: {
        fillerWords: ['hmm', 'uh', 'well'],
        hesitation: 0.3,
        questionFrequency: 0.4,
        detailLevel: 'high',
      },
      Max: {
        fillerWords: ['so', 'well'],
        hesitation: 0.1,
        questionFrequency: 0.2,
        detailLevel: 'precise',
      },
      Jack: {
        fillerWords: ['uh', 'well', 'like'],
        hesitation: 0.15,
        questionFrequency: 0.5,
        detailLevel: 'general',
      },
      Ryan: {
        fillerWords: [],
        hesitation: 0.05,
        questionFrequency: 0.1,
        detailLevel: 'concise',
      },
      Alex: {
        fillerWords: ['hmm', 'you know'],
        hesitation: 0.25,
        questionFrequency: 0.35,
        detailLevel: 'descriptive',
      },
      Leo: {
        fillerWords: ['well'],
        hesitation: 0.1,
        questionFrequency: 0.15,
        detailLevel: 'direct',
      },
    };

    return patterns[this.agentName] || patterns.Ryan;
  }

  /**
   * Get speech-style guidance for the prompt.
   */
  _getSpeechStyleGuidelines() {
    const guidelines = {
      Sam: 'You speak thoughtfully and calmly. You notice details and ask relevant clarifying questions.',
      Max: 'You speak clearly and stay on point. Facts matter more than emotions. Do not use unnecessary words.',
      Jack: 'You are an open and reliable teammate. Speak simply and casually without forced slang.',
      Ryan: 'You are concise. Speak briefly and calmly, without wasting words.',
      Alex: 'You are calm and observant. You sometimes share things you notice.',
      Leo: 'You speak directly and confidently, without unnecessary words.',
    };

    return guidelines[this.agentName] || 'You are a calm, sensible Minecraft player. Speak naturally and stay on point.';
  }

  /**
   * Update mental fatigue from long sessions.
   */
  _updateMentalFatigue() {
    const sessionDuration = Date.now() - this.sessionStartTime;
    const hours = sessionDuration / (1000 * 60 * 60);

    // Fatigue increases logarithmically.
    this.mentalFatigue = Math.min(0.8, Math.log(hours + 1) / 3);
  }

  /**
   * Record a message in the history.
   */
  _recordSpeech(text, situation, timestamp) {
    this.recentSpeech.push({
      text,
      situation,
      timestamp,
    });

    if (this.recentSpeech.length > this.maxRecentSpeech) {
      this.recentSpeech.shift();
    }

    this.lastSpokeTime = timestamp;
  }

  /**
   * Check whether the text is meta-commentary.
   */
  _isMetaComment(text) {
    const metaWords = [
      'character',
      'response',
      'generat',
      'ai',
      'llm',
      'silence',
      'answer to',
      'system',
      'context',
    ];

    const lower = text.toLowerCase();
    return metaWords.some(word => lower.includes(word));
  }

  /**
   * Reset for a new session.
   */
  reset() {
    this.recentSpeech = [];
    this.lastSpokeTime = 0;
    this.mentalFatigue = 0;
    this.sessionStartTime = Date.now();
    this.currentTopic = null;
  }
}
